import CustomCheckbox from '@/components/CrmUi/Checkbox';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { CEDENTE_BANCO_OPTIONS, CEDENTE_ESTADO_CIVIL_OPTIONS, CEDENTE_ESTADO_OPTIONS, CEDENTE_NACIONALIDADE_DEFAULT } from '@/constants/cedentes';
import {
    AGENCIA_CLEAVE_OPTIONS,
    CEP_CLEAVE_OPTIONS,
    CHAVE_ALEATORIA_CLEAVE_OPTIONS,
    CONTA_CLEAVE_OPTIONS,
    CPF_CLEAVE_OPTIONS,
    DATA_CLEAVE_OPTIONS,
    TELEFONE_CLEAVE_OPTIONS,
} from '@/constants/cleave-options';
import { QueryKeys } from '@/constants/query-keys';
import { ProductCombobox, ProductSelect } from '@/design-system';
import { resolveOficioCedentePrefill } from '@/functions/broker/oficio-cedente-prefill';
import {
    buildCedentePfEnrichFillIfEmpty,
    countMissingCedentePfSoftFields,
    shouldSuggestCedentePfEnrich,
} from '@/functions/broker/cedente-pf-enrich-suggestion';
import {
    mapCedenteDataToFormValues,
    shouldHydrateCedenteForm,
} from '@/functions/broker/map-cedente-data-to-form-values';
import { handleCedenteFormValidationFailure, captureCedenteFormEvent } from '@/functions/analytics/cedenteFormValidationUx';
import { applyCedenteFullSchemaValidation } from '@/functions/broker/applyCedenteFullSchemaValidation';
import { CPFAndCNPJMask } from '@/functions/formaters/CPFAndCNPJInput';
import { validationSelectPix } from '@/functions/formaters/validationPix';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import { reverificarExigenciasProposta } from '@/functions/propostas/reverificar-exigencias-proposta';
import {
    useExtratoCedenteDataQuery,
    useOficioLinkedCedentesQuery,
} from '@/hooks/queries/cedentes';
import { useExtratoDataQueryOptions } from '@/hooks/queries/extrato';
import { usePFDataQuery } from '@/hooks/queries/use-direct-data';
import { createNewCedente, updateCedenteInfo } from '@/services/BrokerServices';
import { fetchAddressByCep } from '@/services/cep/fetchAddressByCep';
import { getPFData } from '@/services/direct-data';
import { CedenteEnrichSuggestionBanner } from './CedenteEnrichSuggestionBanner';
import { linkCedenteToExtratoWithAutoEsteira } from '@/services/oficios';
import { PixOption } from '@/types/pix';
import queryClient from '@/utils/queryClient';
import { zodResolver } from '@hookform/resolvers/zod';
import { useMutation, useQuery } from '@tanstack/react-query';
import { AxiosError } from 'axios';
import Cleave from 'cleave.js/react';
import {
    ArrowLeft,
    AtSign,
    BadgeAlert,
    BadgeCheck,
    Banknote,
    BriefcaseBusiness,
    Building,
    Building2,
    CalendarDays,
    CreditCard,
    Flag,
    Home,
    HousePlus,
    IdCard,
    Landmark,
    LoaderCircle,
    Map,
    MapPin,
    Mars,
    Percent,
    Phone,
    Search,
    TriangleAlert,
    University,
    User,
    Venus,
} from 'lucide-react';
import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Controller, FieldErrors, useForm } from 'react-hook-form';
import type { ICedenteRegistrationShellProps } from '../../../interfaces/cedenteRegistrationShell';
import { PixTypeSelect } from '../PixTypeSelect';
import {
    CEDENTE_FIELD_ERROR_CLASS,
    CEDENTE_FIELD_LABEL_CLASS,
    CEDENTE_FORM_GRID_CLASS,
    CEDENTE_FORM_SHELL_CLASS,
    CedenteFormActions,
    CedenteCepLookupStatus,
    CedenteFormBackButton,
    CedenteFormNotice,
    CedenteFormSection,
    CedenteFormSectionHeader,
    getCedenteFormInputClass,
} from './cedenteRegistrationFormUi';
import {
    PF_PARTIAL_CREATE_REQUIRED_FIELDS,
    buildCedenteCreateFormFields,
    pfCedenteFormSchema,
    pfCedentePartialSaveSchema,
    type PfCedenteFormValues,
} from './schemas/cedente-form-schemas';
import { useCedenteRegistrationDeps } from './utils/useCedenteRegistrationDeps';

const RegisterPFCedenteForm = ({
    isFromFormPj = false,
    closeModal,
    backStepForm,
    mode = 'create',
    closePfModalFromPj,
    readonly = false,
    registrationShell,
    onCreated,
}: {
    isFromFormPj?: boolean;
    mode?: 'create' | 'edit' | 'createFromPj';
    closeModal: () => void;
    closePfModalFromPj?: () => void;
    backStepForm?: () => void;
    cedenteId?: string;
    readonly?: boolean;
    registrationShell?: ICedenteRegistrationShellProps;
    onCreated?: (cedente: { id: string; nome: string }) => void;
}) => {
    const { extratoId, cessionPercentageAvailable, representanteLegalId } =
        useCedenteRegistrationDeps(registrationShell);
    const initialTipo = registrationShell?.initialTipo ?? 'PF';

    // ==================
    // # React Queries
    // ==================
    const { data: representanteData, isLoading: isLoadingRepresentanteData } =
        useExtratoCedenteDataQuery(representanteLegalId ?? '');
    const { data: extratoData } = useQuery(useExtratoDataQueryOptions(extratoId));
    const { data: linkedCedentesList, isSuccess: isLinkedCedentesLoaded } =
        useOficioLinkedCedentesQuery(extratoId);
    const vigenteProposalData = extratoData?.propostas?.find((p) => p.vigente);
    const hasLinkedCedente = (linkedCedentesList?.length ?? 0) > 0;

    // ==================
    // # Hook Form
    // ==================
    const {
        register,
        handleSubmit,
        control,
        setValue,
        setFocus,
        getValues,
        setError,
        clearErrors,
        watch,
        formState: { errors, dirtyFields },
    } = useForm<PfCedenteFormValues>({
        resolver: zodResolver(pfCedentePartialSaveSchema),
        shouldFocusError: false,
        // defaultValues (not `values`) — controlled `values` resets fields every render and breaks CPF/CEP autofill
        defaultValues: {
            nacionalidade: CEDENTE_NACIONALIDADE_DEFAULT,
            telefone: '',
            cep: '',
            cpf: '',
            data_nascimento: '',
            rg: '',
            bairro: '',
            municipio: '',
            estado: '',
            complemento: '',
            email: '',
            logradouro: '',
            nome: '',
            nome_mae: '',
            nome_pai: '',
            orgao_exp_rg: '',
            profissao: '',
            tipo: initialTipo,
            agencia: '',
            conta: '',
            pix: '',
            banco: '',
            percentual_cessao: '',
            estado_civil: '',
        },
    });

    const [pixOption, setPixOption] = useState<PixOption>('Telefone');
    const [isSearchingCep, setIsSearchingCep] = useState(false);
    const [isFullPercentage, setIsFullPercentage] = useState(() =>
        cessionPercentageAvailable === 100 ? true : false,
    );
    const [debouncedCpf, setDebouncedCpf] = useState('');
    const [oficioPrefillNotice, setOficioPrefillNotice] = useState<string | null>(null);
    const lastCepLookupDigitsRef = useRef<string | null>(null);
    const hydratedRepresentanteIdRef = useRef<string | null>(null);
    const didPrefillFromOficioRef = useRef(false);
    const nameLockedFromOficioRef = useRef(false);
    const [enrichSuggestionDismissed, setEnrichSuggestionDismissed] = useState(false);
    const [isEnrichingPf, setIsEnrichingPf] = useState(false);
    /** 'partial' = Salvar (soft); 'finalize' = Finalizar Cadastro (full). */
    const saveIntentRef = useRef<'partial' | 'finalize'>('partial');
    let createCedenteToastId: string | number | undefined;

    const currentCpf = watch('cpf') || '';

    const { data: pfData, isLoading: isLoadingPFData } = usePFDataQuery(
        mode === 'create' && debouncedCpf ? debouncedCpf : '',
    );

    // mutations
    const createCedente = useMutation({
        mutationFn: async (paramObj: { data: PfCedenteFormValues; formFields: string[] }) => {
            const { data, formFields } = paramObj;
            const req = await createNewCedente(data as any, formFields);
            return req;
        },
        onMutate: () => {
            const isPartial = saveIntentRef.current === 'partial';
            createCedenteToastId = sendToastMessage({
                title: isPartial ? 'Salvando dados...' : 'Cadastrando cedente...',
                description: 'Este processo pode levar alguns segundos.',
                type: 'loading',
            });
            captureCedenteFormEvent(
                isPartial
                    ? 'crm_broker_cedente_form_save_partial_started'
                    : 'crm_broker_cedente_form_finalize_started',
                { form_tipo: 'PF', mode: mode === 'edit' ? 'edit' : 'create' },
            );
        },
        onError: (error) => {
            if (error instanceof AxiosError) {
                captureCedenteFormEvent(
                    saveIntentRef.current === 'partial'
                        ? 'crm_broker_cedente_form_save_partial_failed'
                        : 'crm_broker_cedente_form_finalize_failed',
                    { form_tipo: 'PF', mode: mode === 'edit' ? 'edit' : 'create', reason: 'api' },
                );
                sendToastMessage({
                    title: error.response?.data.detail || 'Erro ao criar cadastro.',
                    type: 'error',
                    previousToastId: createCedenteToastId,
                });
            }
        },
        onSuccess: async (data, paramObj) => {
            const { data: formData } = paramObj;
            const isPartial = saveIntentRef.current === 'partial';
            captureCedenteFormEvent(
                isPartial
                    ? 'crm_broker_cedente_form_save_partial_succeeded'
                    : 'crm_broker_cedente_form_finalize_succeeded',
                { form_tipo: 'PF', mode: mode === 'edit' ? 'edit' : 'create' },

