'use client';
import { Button } from '@/components/Button';
import CRMTooltip from '@/components/CrmUi/Tooltip';
import { ProductCombobox, ProductConfirmDialog } from '@/design-system';
import BrokerChangePercentualModal from '@/components/Modals/BrokerChangePercentual';
import { CedenteFormSkeleton } from '@/components/Skeletons/Broker/CedenteFormSkeleton';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { estadoCivil } from '@/constants/estado-civil';
import { useDialogBrokerContext } from '@/context/DialogBrokerContext';
import { validationSelectPix } from '@/functions/formaters/validationPix';
import { reverificarExigenciasProposta } from '@/functions/propostas/reverificar-exigencias-proposta';
import {
    useExtratoCedenteDataQuery,
    useOficioLinkedCedentesQuery,
    useRegisteredCedentesListQuery,
} from '@/hooks/queries/cedentes';
import { useExtratoCessionarioUnlinkMutation } from '@/hooks/mutations/useExtratoCessionarioMutations';
import { unlinkRepresentanteFromCedente, updateCedenteInfo } from '@/services/BrokerServices';
import { fetchAddressByCep } from '@/services/cep/fetchAddressByCep';
import { useBrokerStore } from '@/store/useBroker';
import { PixOption } from '@/types/pix';
import { zodResolver } from '@hookform/resolvers/zod';
import { useMutation, useQuery } from '@tanstack/react-query';
import Cleave from 'cleave.js/react';
import {
    Asterisk,
    BriefcaseBusiness,
    CalendarDays,
    File,
    Flag,
    LoaderCircle,
    PencilLine,
    Plus,
    Save,
    Scale,
    Search,
    Trash,
    University,
    Unlink,
    User,
    IdCard,
} from 'lucide-react';

import { useEffect, useMemo, useRef, useState } from 'react';
import { Controller, FieldErrors, useForm } from 'react-hook-form';
import { DialogBroker } from '../../../Modals/BrokersCedente/dialog-broker';

import { QueryKeys } from '@/constants/query-keys';
import {
    captureCedenteFormEvent,
    handleCedenteFormValidationFailure,
} from '@/functions/analytics/cedenteFormValidationUx';
import { sendToastMessage } from '@/functions/messages/toastMessage';
import { sleep } from '@/functions/timer/sleep';
import { useExtratoDataQueryOptions } from '@/hooks/queries/extrato';
import { FormValuesForBrokerCedente } from '@/types/broker';
import queryClient from '@/utils/queryClient';
import { AxiosError } from 'axios';
import {
    PF_PARTIAL_CREATE_REQUIRED_FIELDS,
    PJ_PARTIAL_CREATE_REQUIRED_FIELDS,
    buildCedenteCreateFormFields,
    pfCedenteFormSchema,
    pfCedentePartialSaveSchema,
    pjCedenteFormSchema,
    pjCedentePartialSaveSchema,
    type CedenteFormValues,
} from '../schemas/cedente-form-schemas';
import { applyCedenteFullSchemaValidation } from '@/functions/broker/applyCedenteFullSchemaValidation';
import { measureCedenteFormCompletion } from '@/functions/broker/cedente-form-completion';
import {
    buildCedentePjEnrichFillIfEmpty,
    isCnpjReadyForEnrich,
} from '@/functions/broker/cedente-pj-enrich';
import { debounce } from '@/functions/debounce';
import { usePJDataQuery } from '@/hooks/queries/use-direct-data';
import { CedenteSheetProgress } from './CedenteSheetProgress';
import {
    cedenteSheetFieldClass,
    cedenteSheetFormActionsClass,
    cedenteSheetFormClass,
    cedenteSheetFormGridClass,
    cedenteSheetPercentualActionClass,
    cedenteSheetPercentualClass,
    cedenteSheetPercentualValueClass,
    cedenteSheetSectionClass,
    cedenteSheetSectionContentClass,
    cedenteSheetSectionHeaderClass,
    cedenteSheetSectionTitleClass,
} from '../cedenteSheetClasses';
import { cn } from '@/lib/utils';
import {
    cedenteBentoFormActionsClass,
    cedenteBentoFormClass,
    cedenteBentoFieldClass,
    cedenteBentoFormGridClass,
    cedenteBentoPercentualActionClass,
    cedenteBentoPercentualClass,
    cedenteBentoPercentualValueClass,
    cedenteBentoSectionClass,
    cedenteBentoSectionContentClass,
    cedenteBentoSectionHeaderClass,
    cedenteBentoSectionTitleClass,
} from '@/app/crm/broker/[id]/_components/bentoCedenteClasses';
import { AccordionSections } from './AccordionSections';
import { CedenteEnrichSuggestionBanner } from '../CedenteEnrichSuggestionBanner';
import {
    CEDENTE_REQUIRED_TOOLTIP,
    cedenteInputClassName,
    cedenteProductComboboxTriggerClass,
    type CedenteFormSurface,
} from './CedenteFormField';
import {
    buildCedentePfEnrichFillIfEmpty,
    countMissingCedentePfSoftFields,
    shouldSuggestCedentePfEnrich,
} from '@/functions/broker/cedente-pf-enrich-suggestion';
import {
    mapCedenteDataToFormValues,
    shouldHydrateCedenteForm,
} from '@/functions/broker/map-cedente-data-to-form-values';
import { getPFData } from '@/services/direct-data';

export const EditCedenteForm = ({
    cedenteInfo,
    type,
    hasTitle = true,
    readonly = false,
    embeddedInBento = false,
    surface = 'default',
    hideCessionPercentage = false,
    hideUnlinkFromOficio = false,
    onEditRepresentante,
    onCreateRepresentante,
    prefillRepresentante,
}: {
    hasTitle?: boolean;
    cedenteInfo?: { relation_id: string; id: string };
    type: 'pf' | 'pj';
    readonly?: boolean;
    embeddedInBento?: boolean;
    surface?: CedenteFormSurface;
    hideCessionPercentage?: boolean;
    hideUnlinkFromOficio?: boolean;
    onEditRepresentante?: (representante: { id: string; nome: string }) => void;
    onCreateRepresentante?: () => void;
    prefillRepresentante?: { id: string; nome: string } | null;
}) => {
    const isBrokerSheet = surface === 'broker-sheet';
    // ======================
    // # Store
    // ======================
    const extratoId = useBrokerStore((store) => store.extratoId);

    // ======================
    // # React Queries
    // ======================
    const { data: extratoData } = useQuery(useExtratoDataQueryOptions(extratoId));
    const { data: linkedCedentesList } = useOficioLinkedCedentesQuery(extratoId);
    const { data: cedenteData, isLoading: isLoadingCedenteData } = useExtratoCedenteDataQuery(
        cedenteInfo?.id,
    );
    const { data: registeredCedentesList, isLoading: isLoadingRegisteredCedentesList } =
        useRegisteredCedentesListQuery(type === 'pj');

    // ======================
    // # Context
    // ======================
    const { setRepresentanteLegalId } = useDialogBrokerContext();

    // ======================
    // # Hook Form
    // ======================
    const {
        register,
        handleSubmit,
        control,
        watch,
        setValue,
        setFocus,
        setError,
        clearErrors,
        getValues,
        reset,
        formState: { errors, dirtyFields },
    } = useForm<CedenteFormValues>({
        resolver: zodResolver(type === 'pf' ? pfCedentePartialSaveSchema : pjCedentePartialSaveSchema),
        shouldFocusError: false,
    });

    // ======================
    // # States
    // ======================
    const [isUpdating, setIsUpdating] = useState<boolean>(false);
    const [isUnlinkingRepresentante, setIsUnlinkingRepresentante] = useState(false);
    const [openAccordions, setOpenAccordions] = useState<string[]>([]);
    const [pixOption, setPixOption] = useState<PixOption>('Telefone');
    const [isSearchingCep, setIsSearchingCep] = useState(false);
    const lastCepLookupDigitsRef = useRef<string | null>(null);
    const hydratedCedenteIdRef = useRef<string | null>(null);
    const [enrichDismissedForCedenteId, setEnrichDismissedForCedenteId] = useState<string | null>(
        null,
    );
    const [isEnrichingPf, setIsEnrichingPf] = useState(false);
    const [cnpjToSearch, setCnpjToSearch] = useState('');
    const appliedPjEnrichCnpjRef = useRef<string | null>(null);
    const saveIntentRef = useRef<'partial' | 'finalize'>('partial');

    // ======================
    // # Constants
    // ======================
    const vigenteProposalData = useMemo(
        () => extratoData?.propostas?.find((p) => p.vigente),
        [extratoData],
    );
    const unlinkCedenteMutation = useExtratoCessionarioUnlinkMutation({
        extratoId: extratoId ?? '',
        vigenteProposalUuid: vigenteProposalData?.uuid,
        messageVariant: 'cedente',
    });
    const isInBrokerPage = window.location.pathname.includes('broker');

    // Mapeamento de campos para accordions
    const fieldToAccordionMap: Record<string, string> = {
        // Campos de Endereço
        cep: 'endereco',
        bairro: 'endereco',
        logradouro: 'endereco',
        numero: 'endereco',
        estado: 'endereco',
        complemento: 'endereco',
        municipio: 'endereco',
        // Campos de Contato
        telefone: 'contato',
        email: 'contato',
        // Campos Bancários
        banco: 'bancarios',
        agencia: 'bancarios',
        conta: 'bancarios',
        pix: 'bancarios',
    };

    const registeredCedentesPFList = useMemo(() => {
        return registeredCedentesList?.filter((cedente) => cedente.tipo === 'PF') || [];
    }, [registeredCedentesList]);

    const representanteOptions = useMemo(
        () =>
            registeredCedentesPFList.map((cedente) => ({
                value: cedente.nome,
                label: cedente.nome,
            })),
        [registeredCedentesPFList],
    );

    const estadoCivilOptions = useMemo(
        () => estadoCivil.map((item) => ({ value: item, label: item })),
        [],
    );
    const currentCedenteCessionPercentage = useMemo(() => {
        const currentCedente = linkedCedentesList?.find(
            (vinculo) => vinculo.cedente.id === cedenteInfo?.id,
        );
        return currentCedente?.percentual_cessao || '0';
    }, [cedenteData, cedenteInfo?.id, linkedCedentesList]);

    const { data: pjData, isLoading: isLoadingPJData } = usePJDataQuery(
        type === 'pj' ? cnpjToSearch : '',
    );
    const debouncedSetCnpjToSearch = useMemo(
        () =>
            debounce((cnpj: string) => {
                if (isCnpjReadyForEnrich(cnpj)) {
                    setCnpjToSearch(cnpj);
                    return;
                }
                setCnpjToSearch('');
            }, 800),
        [],
    );

    const watchedCpf = watch('cpf');
    const watchedCnpj = watch('cnpj');
    const watchedFormValues = watch();
    const sheetCompletion = useMemo(
        () => measureCedenteFormCompletion(watchedFormValues as Record<string, unknown>, type),
        [watchedFormValues, type],
    );
    const watchedSoftFields = watch([
        'rg',
        'data_nascimento',
        'estado_civil',
        'profissao',
        'nome_mae',
        'nome_pai',
        'nacionalidade',
        'telefone',
        'email',
        'cep',
        'nome',
        'logradouro',
        'numero',
        'complemento',
        'bairro',
        'municipio',
        'estado',
    ]);

    const pfEnrichFormValues = useMemo(
        () => ({
            cpf: watchedCpf,
            rg: watchedSoftFields[0],
            data_nascimento: watchedSoftFields[1],
            estado_civil: watchedSoftFields[2],
            profissao: watchedSoftFields[3],
            nome_mae: watchedSoftFields[4],
            nome_pai: watchedSoftFields[5],
            nacionalidade: watchedSoftFields[6],
            telefone: watchedSoftFields[7],
            email: watchedSoftFields[8],
            cep: watchedSoftFields[9],
            nome: watchedSoftFields[10],
            logradouro: watchedSoftFields[11],
            numero: watchedSoftFields[12],
            complemento: watchedSoftFields[13],
            bairro: watchedSoftFields[14],
            municipio: watchedSoftFields[15],
            estado: watchedSoftFields[16],
        }),
        [watchedCpf, watchedSoftFields],
    );

    const pfMissingSoftCount = useMemo(
        () => countMissingCedentePfSoftFields(pfEnrichFormValues),
        [pfEnrichFormValues],
    );

    const showPfEnrichSuggestion =
        type === 'pf' &&
        shouldSuggestCedentePfEnrich({
            cpf: watchedCpf,
            values: pfEnrichFormValues,
            dismissed: enrichDismissedForCedenteId === (cedenteInfo?.id ?? null),
            readonly,
        });

    useEffect(() => {
        // Trocar de cedente reexibe a sugestão nesta sessão.
        setEnrichDismissedForCedenteId(null);
        appliedPjEnrichCnpjRef.current = null;
        setCnpjToSearch('');
    }, [cedenteInfo?.id]);

    useEffect(() => {
        if (!prefillRepresentante?.nome) return;
        setValue('representante_legal', prefillRepresentante.nome, { shouldDirty: true });
    }, [prefillRepresentante, setValue]);

    useEffect(() => {
        if (type !== 'pj') return;
        const currentCnpjDigits = String(watchedCnpj ?? '').replace(/\D/g, '');
        if (!cnpjToSearch || appliedPjEnrichCnpjRef.current === currentCnpjDigits) return;

        if (!pjData?.retorno || pjData.metaDados.resultadoId !== 1) {
            if (pjData && pjData.metaDados.resultadoId !== 1) {
                appliedPjEnrichCnpjRef.current = currentCnpjDigits;
                sendToastMessage({
                    title: 'Não encontramos dados para este CNPJ.',
                    type: 'warning',
                });
            }
            return;
        }

        const fill = buildCedentePjEnrichFillIfEmpty(
            {
                razao_social: getValues('razao_social'),
                telefone: getValues('telefone'),
                email: getValues('email'),
                cep: getValues('cep'),
                logradouro: getValues('logradouro'),
                numero: getValues('numero'),
                complemento: getValues('complemento'),
                bairro: getValues('bairro'),
                municipio: getValues('municipio'),
                estado: getValues('estado'),
            },
            pjData.retorno,
        );

        const filledKeys = Object.keys(fill);
        appliedPjEnrichCnpjRef.current = currentCnpjDigits;

        if (filledKeys.length === 0) {
            sendToastMessage({
                title: 'Nenhum campo vazio pôde ser preenchido com a consulta.',
                type: 'info',
            });
            return;
        }

        for (const [key, value] of Object.entries(fill)) {
            if (value == null) continue;
            setValue(key as keyof CedenteFormValues, String(value), { shouldDirty: true });
        }

        if (fill.cep || fill.logradouro || fill.municipio) {
            setOpenAccordions((prev) =>
                prev.includes('endereco') ? prev : [...prev, 'endereco'],
            );
        }
        if (fill.telefone || fill.email) {
            setOpenAccordions((prev) =>
                prev.includes('contato') ? prev : [...prev, 'contato'],
            );
        }

        sendToastMessage({
            title: 'Ativos Intelligence preencheu os campos vazios. Revise antes de salvar.',
            type: 'success',
        });
    }, [cnpjToSearch, getValues, pjData, setValue, type, watchedCnpj]);

    // ======================
    // # Functions
    // ======================

    async function handleEnrichPfFromDirectData() {
        if (!watchedCpf || isEnrichingPf) return;
        setIsEnrichingPf(true);
        try {
            const response = await getPFData(watchedCpf);
            if (!response?.retorno) {
                sendToastMessage({
                    title: 'Não encontramos dados para este CPF.',
                    type: 'warning',
                });
                return;
            }

            const fill = buildCedentePfEnrichFillIfEmpty(pfEnrichFormValues, response.retorno);
            const filledKeys = Object.keys(fill);
            if (filledKeys.length === 0) {
                sendToastMessage({
                    title: 'Nenhum campo vazio pôde ser preenchido com a consulta.',
                    type: 'info',
                });
                return;
            }

            for (const [key, value] of Object.entries(fill)) {
                if (value == null) continue;
                setValue(key as keyof CedenteFormValues, String(value), {
                    shouldDirty: true,
                });
            }

            if (fill.cep || fill.logradouro || fill.municipio) {
                setOpenAccordions((prev) =>
                    prev.includes('endereco') ? prev : [...prev, 'endereco'],
                );
            }
            if (fill.telefone || fill.email) {
                setOpenAccordions((prev) =>
                    prev.includes('contato') ? prev : [...prev, 'contato'],
                );
            }

            sendToastMessage({
                title: 'Ativos Intelligence preencheu os campos vazios. Revise antes de salvar.',
                type: 'success',
            });
        } catch (error) {
            const message =
                error instanceof Error && error.message
                    ? error.message
                    : 'Falha ao consultar dados do CPF.';
            sendToastMessage({ title: message, type: 'error' });
        } finally {
            setIsEnrichingPf(false);
        }
    }

    function openAccordionForPath(firstPath: string) {
        const root = firstPath.split('.')[0] ?? firstPath;
        const accordionToOpen = fieldToAccordionMap[root] ?? fieldToAccordionMap[firstPath];
        if (!accordionToOpen) return;
        setOpenAccordions((prev) =>
            prev.includes(accordionToOpen) ? prev : [...prev, accordionToOpen],
        );
    }

    async function persistCedente(data: CedenteFormValues) {
        const requiredKeys =
            type === 'pf' ? PF_PARTIAL_CREATE_REQUIRED_FIELDS : PJ_PARTIAL_CREATE_REQUIRED_FIELDS;
        const modifiedFormFields = buildCedenteCreateFormFields(
            data as unknown as Record<string, unknown>,
            dirtyFields,
            requiredKeys,
        );

        if (data.telefone) {
            data.telefone = data.telefone.replace(/\D/g, ''); // remove tudo que não for dígito
        }

        if (data.numero) {
            if (/^\d+$/.test(String(data.numero))) {
                data.numero = String(data.numero);
            } else {
                sendToastMessage({
                    title: 'Erro',
                    description: 'O campo número deve ser preenchido apenas com números.',
                    type: 'error',
                });
                return;
            }
        }

        if (type === 'pf' && 'data_nascimento' in data && data.data_nascimento) {
            data.data_nascimento = data.data_nascimento.split('/').reverse().join('-');
        }

        if (type === 'pj' && 'representante_legal' in data && data.representante_legal) {
            const prefilledNome = prefillRepresentante?.nome.trim();
            const representanteId =
                prefillRepresentante && prefilledNome === data.representante_legal?.trim()
                    ? prefillRepresentante.id
                    : registeredCedentesPFList.find(
                          (cedente) => cedente.nome.trim() === data.representante_legal?.trim(),
                      )?.id;
            if (representanteId) {
                data.representante_legal_id = representanteId;
            }
            delete data.representante_legal;
        }

        if (modifiedFormFields.length > 0) {
            await updateCedente.mutateAsync({
                data,
                formFields: modifiedFormFields,
            });
        } else {
            sendToastMessage({
                title: 'Atenção',
                description: 'É necessário ao menos modificar um campo para atualizar os dados.',
                type: 'warning',
            });
        }
    }

    async function onSubmit(data: CedenteFormValues) {
        saveIntentRef.current = 'partial';
        await persistCedente(data);
    }

    function onFinalizeClick() {
        saveIntentRef.current = 'finalize';
        const values = getValues();
        const isValid = applyCedenteFullSchemaValidation({
            schema: type === 'pf' ? pfCedenteFormSchema : pjCedenteFormSchema,
            values,
            setError,
            clearErrors,
            formTipo: type === 'pj' ? 'PJ' : 'PF',
            mode: 'edit',
            setFocus: (name) => setFocus(name as Parameters<typeof setFocus>[0]),
            onBeforeScroll: openAccordionForPath,
        });
        if (!isValid) return;
        void persistCedente(values);
    }

    function onFormFailure(formErrors: FieldErrors<CedenteFormValues>) {
        handleCedenteFormValidationFailure({
            errors: formErrors,
            formTipo: type === 'pj' ? 'PJ' : 'PF',
            mode: 'edit',
            setFocus: (name) => setFocus(name as Parameters<typeof setFocus>[0]),
            onBeforeScroll: openAccordionForPath,
        });
    }

    const updateCedente = useMutation({
        mutationFn: async (paramObj: { data: CedenteFormValues; formFields: string[] }) => {
            const { data, formFields } = paramObj;
            await updateCedenteInfo(
                data as unknown as FormValuesForBrokerCedente,
                formFields,
                cedenteInfo?.id as string,
            );
        },
        onMutate: async () => {
            setIsUpdating(true);
        },
        onError: (error) => {
            if (error instanceof AxiosError) {
                sendToastMessage({
                    title: error.response?.data.detail || 'Erro ao atualizar cedente',
                    type: 'error',
                });
            }
        },
        onSuccess: async () => {
            const isPartial = saveIntentRef.current === 'partial';
            captureCedenteFormEvent(
                isPartial
                    ? 'crm_broker_cedente_form_save_partial_succeeded'
                    : 'crm_broker_cedente_form_finalize_succeeded',
                {
                    form_tipo: type === 'pj' ? 'PJ' : 'PF',
                    mode: 'edit',
                },
            );
            sendToastMessage({
                title: isPartial
                    ? 'Dados salvos. Você pode continuar preenchendo.'
                    : 'Cadastro finalizado.',
                type: 'success',
            });

            queryClient.invalidateQueries({ queryKey: [QueryKeys.cedentes.data, cedenteInfo?.id] });
            await reverificarExigenciasProposta(queryClient, vigenteProposalData?.uuid);
            queryClient.invalidateQueries({
                queryKey: [QueryKeys.cedentes.linkedExtratoCedentes, extratoId],
            });
            queryClient.invalidateQueries({
                queryKey: [QueryKeys.oficios.item, extratoId],
            });
            queryClient.invalidateQueries({
                queryKey: [QueryKeys.cedentes.linkedEsteirasCedente],
            });
            reset(undefined, { keepValues: true });
            setIsUpdating(false);
        },
    });

    const handleUnlinkCedente = () => {
        if (!cedenteInfo?.relation_id || !extratoId) return;
        unlinkCedenteMutation.mutate(cedenteInfo.relation_id);
    };

