import { CedenteFormSkeleton } from '@/components/Skeletons/Broker/CedenteFormSkeleton';
import { BrokerOficioLockedEmptyState } from '@/components/ErrorMessage/BrokerOficioLockedEmptyState';
import { LockedSectionTooltip } from '@/components/Tooltips/LockedSectionTooltip';
import { Tabs, TabsList } from '@/components/ui/tabs';
import { DialogBrokerContextProvider } from '@/context/DialogBrokerContext';
import {
    filterCedenteLinks,
    filterVisibleCedenteLinks,
} from '@/functions/broker/cedente-cession-percentage';
import { resolveActiveCedenteFromLinks } from '@/functions/broker/resolve-active-cedente-from-links';
import { resolveCedenteSuggestionNotice } from '@/functions/broker/cedente-suggestion-notice';
import type { OficioLockReason } from '@/functions/broker/oficio-lock-state';
import { useEnsureCedenteFromOficio } from '@/hooks/broker/useEnsureCedenteFromOficio';
import { useExtratoCedenteDataQuery, useOficioLinkedCedentesQuery } from '@/hooks/queries/cedentes';
import { useExtratoDataQueryOptions } from '@/hooks/queries/extrato';
import { useBrokerStore } from '@/store/useBroker';
import { OficioLinkedCedente } from '@/types/oficio';
import { Link, Plus, UserRound } from 'lucide-react';
import Image from 'next/image';
import { cn } from '@/lib/utils';
import React, { useEffect, useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { DialogBroker } from '../../Modals/BrokersCedente/dialog-broker';
import { Button } from '../../ui/button';
import { CedenteLinkTab } from './CedenteLinkTab';
import { EditCedenteForm } from './EditCedenteForm';
import {
    cedenteBentoFormShellClass,
    cedenteBentoTabsListClass,
    cedenteBentoToolbarClass,
    cedenteBentoToolbarHintClass,
} from '@/app/crm/broker/[id]/_components/bentoCedenteClasses';
import { useIsGerencialOficioDetail } from '@/app/crm/gerencial-broker/_hooks/useIsGerencialOficioDetail';
import {
    GERENCIAL_OFICIO_SECTION_CLASS,
    gerencialOficioSectionStyle,
} from '@/app/crm/gerencial-broker/_components/shared/GerencialOficioSectionCard';
import { COLORS } from '@/app/crm/gerencial-broker/_constants/colors';
import { withAlpha } from '@/design-system';
import { useBentoCockpitTheme } from '@/app/crm/broker/_hooks/useBentoCockpitTheme';

interface BrokerCedenteFormProps {
    isLocked?: boolean;
    lockReason?: OficioLockReason;
    embeddedInBento?: boolean;
    /** `broker-sheet` veste o shell bento com os tokens da gaveta do broker. */
    surface?: 'default' | 'broker-sheet';
    onEditRepresentante?: (representante: { id: string; nome: string }) => void;
    onCreateRepresentante?: () => void;
    prefillRepresentante?: { id: string; nome: string } | null;
}

const BrokerCedenteForm = ({
    isLocked = false,
    lockReason,
    embeddedInBento = false,
    surface = 'default',
    onEditRepresentante,
    onCreateRepresentante,
    prefillRepresentante,
}: BrokerCedenteFormProps) => {
    const isBrokerSheet = surface === 'broker-sheet';
    const isGerencialOficioDetail = useIsGerencialOficioDetail();
    const { theme } = useBentoCockpitTheme();
    const extratoId = useBrokerStore((state) => state.extratoId);
    const activeCedente = useBrokerStore((state) => state.activeCedente);
    const setActiveCedente = useBrokerStore((state) => state.setActiveCedente);

    const { isLoading: isLoadingCedenteData } = useExtratoCedenteDataQuery(activeCedente?.id);
    const { data: linkedCedentesList, isLoading: isLoadingLinkedCedenteList } =
        useOficioLinkedCedentesQuery(extratoId);
    const { data: extratoData, isLoading: isLoadingExtrato } = useQuery(
        useExtratoDataQueryOptions(extratoId ?? ''),
    );

    const hasCedente = filterCedenteLinks(linkedCedentesList).length > 0;
    const filteredLinkedCedentesList = useMemo(
        () => filterVisibleCedenteLinks(linkedCedentesList),
        [linkedCedentesList],
    );

    const { isEnsuring, suggestion } = useEnsureCedenteFromOficio({
        extratoId,
        hasLinkedCedente: hasCedente,
        isLoadingLinks: isLoadingLinkedCedenteList || isLoadingExtrato,
        oficioCredor: extratoData?.credor,
        oficioCpfCnpj: extratoData?.cpf_cnpj,
        enabled: !isLocked,
    });

    const suggestionNotice = useMemo(
        () => resolveCedenteSuggestionNotice(suggestion),
        [suggestion],
    );

    const calculateActiveCedente = React.useCallback(
        () => resolveActiveCedenteFromLinks(filteredLinkedCedentesList, activeCedente),
        [filteredLinkedCedentesList, activeCedente],
    );

    useEffect(() => {
        const newActiveCedente = calculateActiveCedente();
        setActiveCedente(newActiveCedente);
    }, [linkedCedentesList]);

    function handleChangeCedente(vinculo: OficioLinkedCedente) {
        if (vinculo.cedente.id === activeCedente?.id) return;

        setActiveCedente({
            relation_id: vinculo.id,
            nome: vinculo.cedente.nome,
            id: vinculo.cedente.id,
            tipo: vinculo.cedente.tipo,
        });
    }

    if (isLoadingLinkedCedenteList || (!hasCedente && isLoadingExtrato) || isEnsuring) {
        return <CedenteFormSkeleton surface={surface} />;
    }

    if (isLocked && lockReason && !hasCedente) {
        return (
            <BrokerOficioLockedEmptyState
                lockReason={lockReason}
                context="cedente"
                className="col-span-12"
                illustration="cedente"
            />
        );
    }

    return (
        <DialogBrokerContextProvider>
            <div
                className={cn(
                    embeddedInBento
                        ? cedenteBentoFormShellClass
                        : isGerencialOficioDetail
                          ? cn(GERENCIAL_OFICIO_SECTION_CLASS, 'p-4 md:p-5')
                          : 'relative col-span-12 rounded-md border bg-boxdark p-4 shadow-default',
                )}
                {...(embeddedInBento ? { 'data-cedente-scroll-root': '' } : {})}
                style={
                    !embeddedInBento && isGerencialOficioDetail
                        ? gerencialOficioSectionStyle
                        : undefined
                }
            >
                {!embeddedInBento && (
                    <>
                        <div className="absolute right-4 top-4 z-10">
                            {isLocked && <LockedSectionTooltip lockReason={lockReason} />}
                        </div>
                        {hasCedente && (
                            <div className="absolute right-4 top-4 z-0">
                                <DialogBroker
                                    triggerButton={
                                        <Button
                                            variant="outline-default"
                                            className={cn(
                                                'h-fit gap-3 text-sm',
                                                isGerencialOficioDetail &&
                                                    'rounded-lg font-semibold',
                                            )}
                                            style={
                                                isGerencialOficioDetail
                                                    ? {
                                                          borderColor: withAlpha(COLORS.blue, 0.35),
                                                          color: COLORS.blue,
                                                      }
                                                    : undefined
                                            }
                                            disabled={isLocked}
                                        >
                                            <Plus size={20} />
                                            <p className="hidden md:block">Novo Cedente</p>
                                        </Button>
                                    }
                                />
                            </div>
                        )}
                    </>
                )}
                <div className={isLocked ? 'pointer-events-none opacity-50' : ''}>
                    {hasCedente ? (
                        <>
                            {!embeddedInBento && (
                                <div className="mb-4 max-w-[250px] space-y-1 md:max-w-full">
                                    {isGerencialOficioDetail ? (
                                        <div className="flex items-center gap-3">
                                            <div
                                                className="flex h-9 w-9 items-center justify-center rounded-full"
                                                style={{
                                                    background: withAlpha(COLORS.blue, 0.12),
                                                    border: `1px solid ${withAlpha(COLORS.blue, 0.22)}`,
                                                }}
                                            >
                                                <UserRound
                                                    size={16}
                                                    style={{ color: COLORS.blue }}
                                                    aria-hidden
                                                />
                                            </div>
                                            <div>
                                                <h2
                                                    className="font-nexa text-base font-bold md:text-lg"
                                                    style={{ color: COLORS.text }}
                                                >
                                                    Informações do cedente
                                                </h2>
                                                <p
                                                    className="text-xs font-satoshi"
                                                    style={{ color: COLORS.textDim }}
                                                >
                                                    Selecione um cedente abaixo para visualizar suas
                                                    informações
                                                </p>
                                            </div>
                                        </div>
                                    ) : (
                                        <>
                                            <h2 className="text-base font-medium text-subtitle sm:text-lg">
                                                Informações do cedente
                                            </h2>
                                            <p className="text-sm text-paragraph">
                                                Selecione um cedente abaixo para visualizar suas
                                                informações
                                            </p>
                                        </>
                                    )}
                                </div>
                            )}
                            {embeddedInBento && (
                                <div className={cedenteBentoToolbarClass}>
                                    <p className={cedenteBentoToolbarHintClass}>
                                        Selecione um cedente para visualizar e editar suas informações
                                    </p>
                                    <div className="flex shrink-0 items-center gap-2">
                                        {isLocked && <LockedSectionTooltip lockReason={lockReason} />}
                                        <DialogBroker
                                            surface={surface}
                                            triggerButton={
                                                <Button
                                                    variant="outline-default"
                                                    className={cn(
                                                        'h-[30px] gap-1.5 rounded-lg px-2.5 text-[11px]',
                                                        isBrokerSheet &&
                                                            'border-celer-blue/30 bg-celer-blue/5 text-celer-blue hover:bg-celer-blue/10',
                                                    )}
                                                    disabled={isLocked}
                                                >
                                                    <Plus size={14} />
                                                    <span className="hidden min-[400px]:inline">
                                                        Novo Cedente
                                                    </span>
                                                </Button>
                                            }
                                        />
                                    </div>
                                </div>
                            )}
                            <Tabs
                                style={{
                                    scrollbarWidth: 'thin',
                                    scrollbarColor: '#efefef transparent',
                                }}
                                value={activeCedente?.relation_id || ''}
                                className={cn(
                                    embeddedInBento
                                        ? 'cedente-bento-tabs mb-3 w-full'
                                        : 'mb-4 w-[1200px]',
                                )}
                            >
                                <TabsList
                                    className={cn(
                                        'tabs-scrollbar justify-normal overflow-x-auto overflow-y-hidden',
                                        embeddedInBento
                                            ? cn('w-full max-w-full', cedenteBentoTabsListClass)
                                            : 'w-fit md:max-w-[calc(100%-40px)]',
                                    )}
                                >
                                    {filteredLinkedCedentesList?.map((vinculo) => (
                                        <CedenteLinkTab
                                            key={`vinculo-${vinculo.id}`}
                                            vinculo={vinculo}
                                            extratoId={extratoId ?? ''}
                                            vigenteProposalUuid={
                                                extratoData?.propostas?.find((p) => p.vigente)?.uuid
                                            }
                                            embeddedInBento={embeddedInBento}
                                            disabled={isLoadingCedenteData || isLocked}
                                            onSelect={handleChangeCedente}
                                        />
                                    ))}
                                </TabsList>
                            </Tabs>

                            {activeCedente?.tipo === 'PF' ? (
                                <EditCedenteForm
                                    cedenteInfo={{
                                        relation_id: activeCedente?.relation_id ?? '',
                                        id: activeCedente?.id ?? '',
                                    }}
                                    type="pf"
                                    hasTitle={false}
                                    embeddedInBento={embeddedInBento}
                                    surface={surface}
                                />
                            ) : (
                                <EditCedenteForm
                                    cedenteInfo={{
                                        relation_id: activeCedente?.relation_id ?? '',
                                        id: activeCedente?.id ?? '',
                                    }}
                                    type="pj"
                                    hasTitle={false}
                                    embeddedInBento={embeddedInBento}
                                    surface={surface}
                                    onEditRepresentante={onEditRepresentante}
                                    onCreateRepresentante={onCreateRepresentante}
                                    prefillRepresentante={prefillRepresentante}
                                />
                            )}
                        </>
                    ) : (
                        <div
                            className="flex h-full min-h-0 flex-col items-center justify-center gap-4 px-4 py-6 text-center"
                            role="status"
                            aria-label={
                                suggestion?.suggested_cedente_id
                                    ? 'Cedente sugerido'
                                    : 'Nenhum cedente vinculado'
                            }
                        >
                            <div className="relative h-48 w-48">
                                <Image
                                    src="/assets/illustrations/acordo.png"
                                    alt=""
                                    fill
                                    className="object-contain"
                                    sizes="12rem"
                                    aria-hidden
                                    priority={false}
                                />
                            </div>

                            <div className="max-w-md space-y-2">
                                <h3
                                    className="text-lg font-semibold"
                                    style={{ color: theme.text }}

