'use client';

import RegisterPFCedenteForm from '@/components/Forms/Broker/RegisterPFCedenteForm';
import RegisterPJCedenteForm from '@/components/Forms/Broker/RegisterPJCedenteForm';
import { Dialog } from '@/components/ui/dialog';
import {
    ProductDialogContent,
    ProductDialogDescription,
    ProductDialogHeader,
    ProductDialogTitle,
    productDialogBodyClass,
} from '@/design-system';
import type { ICedenteRegistrationShellProps } from '@/interfaces/cedenteRegistrationShell';
import { cn } from '@/lib/utils';
import { Building2, Percent, User, type LucideIcon } from 'lucide-react';
import { useCallback, useMemo, useState } from 'react';
import type { TCedenteTipo } from '../../../types/situacaoJuridica';
import {
    getCadastroCedenteModalTitle,
    getCessionPercentageBadgeClass,
} from '../../../utils/cadastroCedenteModal';

export interface ICadastroCedenteSituacaoJuridicaModalProps {
    isOpen: boolean;
    cedenteTipo: TCedenteTipo;
    extratoId: string;
    dueId?: string;
    cessionPercentageAvailable: number;
    onClose: () => void;
}

function getCadastroCedenteModalTitleIcon(
    cedenteTipo: TCedenteTipo,
    isRepresentanteFlow: boolean,
): LucideIcon {
    if (isRepresentanteFlow) return User;
    if (cedenteTipo === 'PJ') return Building2;
    return User;
}

export function CadastroCedenteSituacaoJuridicaModal({
    isOpen,
    cedenteTipo,
    extratoId,
    cessionPercentageAvailable,
    onClose,
}: ICadastroCedenteSituacaoJuridicaModalProps) {
    const [showNestedPfRepresentante, setShowNestedPfRepresentante] = useState(false);
    const [representanteLegalId, setRepresentanteLegalId] = useState<string | null>(null);

    const handleCloseModal = useCallback(() => {
        setShowNestedPfRepresentante(false);
        setRepresentanteLegalId(null);
        onClose();
    }, [onClose]);

    const registrationShell = useMemo<ICedenteRegistrationShellProps>(
        () => ({
            extratoId,
            cessionPercentageAvailable,
            onClose: handleCloseModal,
            initialTipo: cedenteTipo === 'ES' ? 'ES' : 'PF',
            representanteLegalId,
            setRepresentanteLegalId,
        }),
        [
            cedenteTipo,
            cessionPercentageAvailable,
            extratoId,
            handleCloseModal,
            representanteLegalId,
        ],
    );

    const modalTitle = showNestedPfRepresentante
        ? 'Cadastrar representante'
        : getCadastroCedenteModalTitle(cedenteTipo);

    const TitleIcon = getCadastroCedenteModalTitleIcon(
        cedenteTipo,
        showNestedPfRepresentante,
    );

    return (
        <Dialog
            open={isOpen}
            onOpenChange={(open) => {
                if (!open) handleCloseModal();
            }}
        >
            <ProductDialogContent
                size="xl"
                hideClose={false}
                className="flex min-h-[min(82vh,52rem)] max-h-[92vh] w-[calc(100vw-2rem)] max-w-4xl! flex-col"
            >
                <ProductDialogHeader>
                    <ProductDialogTitle className="flex items-center gap-2">
                        <TitleIcon size={18} aria-hidden />
                        {modalTitle}
                    </ProductDialogTitle>
                    {showNestedPfRepresentante ? (
                        <ProductDialogDescription className="sr-only">
                            Formulário para cadastrar o representante legal da pessoa jurídica.
                        </ProductDialogDescription>
                    ) : (
                        <>
                            <ProductDialogDescription className="sr-only">
                                Formulário de cadastro de cedente com percentual de cessão
                                disponível de {cessionPercentageAvailable.toFixed(2)} por cento.
                            </ProductDialogDescription>
                            <div className="pt-1">
                                <span
                                    className={cn(
                                        'inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 font-satoshi text-[11px] font-bold',
                                        getCessionPercentageBadgeClass(cessionPercentageAvailable),
                                    )}
                                >
                                    <Percent size={12} aria-hidden />
                                    Percentual de cessão disponível:{' '}
                                    {cessionPercentageAvailable.toFixed(2)}%
                                </span>
                            </div>
                        </>
                    )}
                </ProductDialogHeader>

                <div
                    className={cn(
                        productDialogBodyClass,
                        'min-h-0 flex-1 max-h-[calc(92vh-10rem)] scrollbar-gutter-stable *:min-w-0',
                    )}
                >
                    {showNestedPfRepresentante ? (
                        <RegisterPFCedenteForm
                            isFromFormPj
                            mode="createFromPj"
                            closeModal={handleCloseModal}
                            closePfModalFromPj={() => setShowNestedPfRepresentante(false)}
                            backStepForm={() => setShowNestedPfRepresentante(false)}
                            registrationShell={registrationShell}
                        />
                    ) : cedenteTipo === 'PJ' ? (
                        <RegisterPJCedenteForm
                            closeModal={handleCloseModal}
                            backStepForm={handleCloseModal}
                            openRegisterPFForm={() => setShowNestedPfRepresentante(true)}
                            registrationShell={registrationShell}
                        />
                    ) : (
                        <RegisterPFCedenteForm
                            mode="create"
                            closeModal={handleCloseModal}
                            registrationShell={registrationShell}
                        />
                    )}
                </div>
            </ProductDialogContent>
        </Dialog>
    );
}

