'use client';

import { EditCedenteForm } from '@/components/Forms/Broker/EditCedenteForm';
import RegisterPFCedenteForm from '@/components/Forms/Broker/RegisterPFCedenteForm';
import { DialogBrokerContextProvider } from '@/context/DialogBrokerContext';
import { ProductSheetHeader, ProductSheetTitle } from '@/design-system';
import { cn } from '@/lib/utils';
import { ArrowLeft } from 'lucide-react';
import { INICIO_GHOST_INSTRUMENT_CLASS } from '../../_constants/surfaces';

export type GavetaRepresentanteMode = 'edit' | 'create';

interface GavetaRepresentanteLegalProps {
    mode: GavetaRepresentanteMode;
    representanteId?: string;
    representanteNome?: string;
    onBack: () => void;
    onCreated: (cedente: { id: string; nome: string }) => void;
}

export function GavetaRepresentanteLegal({
    mode,
    representanteId,
    representanteNome,
    onBack,
    onCreated,
}: GavetaRepresentanteLegalProps) {
    const isEditing = mode === 'edit' && Boolean(representanteId);

    return (
        <>
            <ProductSheetHeader className="flex items-center gap-3">
                <button
                    type="button"
                    onClick={onBack}
                    aria-label="Voltar para o cadastro do credor"
                    className={cn(
                        INICIO_GHOST_INSTRUMENT_CLASS,
                        'grid size-9 shrink-0 place-items-center rounded-xl',
                    )}
                >
                    <ArrowLeft className="size-4" aria-hidden />
                </button>

                <div className="min-w-0 flex-1">
                    <ProductSheetTitle className="truncate text-base leading-tight">
                        Representante legal
                    </ProductSheetTitle>
                    <p className="text-celer-muted mt-1 truncate text-[11px]">
                        {isEditing
                            ? representanteNome || 'Registro PF vinculado'
                            : 'Novo cadastro PF — o vínculo no cedente PJ acontece ao salvar'}
                    </p>
                </div>
            </ProductSheetHeader>

            <div className="min-h-0 flex-1 overflow-y-auto px-5 py-4 sm:px-6">
                {isEditing ? (
                    <EditCedenteForm
                        type="pf"
                        hasTitle={false}
                        embeddedInBento
                        surface="broker-sheet"
                        hideCessionPercentage
                        hideUnlinkFromOficio
                        cedenteInfo={{
                            id: representanteId as string,
                            relation_id: '',
                        }}
                    />
                ) : (
                    <DialogBrokerContextProvider>
                        <RegisterPFCedenteForm
                            mode="createFromPj"
                            isFromFormPj
                            closeModal={onBack}
                            closePfModalFromPj={onBack}
                            onCreated={onCreated}
                        />
                    </DialogBrokerContextProvider>
                )}
            </div>
        </>
    );
}

