'use client';

import { useState } from 'react';
import BrokerCedenteForm from '@/components/Forms/Broker/BrokerCedenteForm';
import { ProductSheetHeader, ProductSheetTitle } from '@/design-system';
import { LIQUID_INSTRUMENT_FACET_CLASS } from '@/design-system/tokens/liquid-facet';
import { cn } from '@/lib/utils';
import { useBrokerStore } from '@/store/useBroker';
import { ArrowLeft } from 'lucide-react';
import { INICIO_GHOST_INSTRUMENT_CLASS } from '../../_constants/surfaces';
import { GavetaRepresentanteLegal, type GavetaRepresentanteMode } from './GavetaRepresentanteLegal';

interface GavetaCadastroCredorProps {
    onBack: () => void;
}

type CadastroSubview =
    | { kind: 'form' }
    | { kind: 'representante'; mode: GavetaRepresentanteMode; id?: string; nome?: string };

export function GavetaCadastroCredor({ onBack }: GavetaCadastroCredorProps) {
    const activeCedente = useBrokerStore((store) => store.activeCedente);
    const [subview, setSubview] = useState<CadastroSubview>({ kind: 'form' });
    const [prefillRepresentante, setPrefillRepresentante] = useState<{
        id: string;
        nome: string;
    } | null>(null);

    if (subview.kind === 'representante') {
        return (
            <GavetaRepresentanteLegal
                mode={subview.mode}
                representanteId={subview.id}
                representanteNome={subview.nome}
                onBack={() => setSubview({ kind: 'form' })}
                onCreated={(cedente) => {
                    setPrefillRepresentante(cedente);
                    setSubview({ kind: 'form' });
                }}
            />
        );
    }

    return (
        <>
            <ProductSheetHeader className="flex items-center gap-3">
                <button
                    type="button"
                    onClick={onBack}
                    aria-label="Voltar para o resumo da operação"
                    className={cn(
                        INICIO_GHOST_INSTRUMENT_CLASS,
                        'grid size-9 shrink-0 place-items-center rounded-xl',
                    )}
                >
                    <ArrowLeft className="size-4" aria-hidden />
                </button>

                <div className="min-w-0 flex-1">
                    <ProductSheetTitle className="truncate text-base leading-tight">
                        Cadastro do credor
                    </ProductSheetTitle>
                    <p className="text-celer-muted mt-1 truncate text-[11px]">
                        {activeCedente?.nome || 'Dados cadastrais e vínculos'}
                    </p>
                </div>

                {activeCedente?.tipo && (
                    <span
                        className={cn(
                            LIQUID_INSTRUMENT_FACET_CLASS,
                            'border-celer-blue/20 bg-celer-blue/10 text-celer-blue shrink-0 rounded-full border px-2 py-0.5 text-[10px] font-semibold',
                        )}
                    >
                        {activeCedente.tipo === 'PJ' ? 'Pessoa jurídica' : 'Pessoa física'}
                    </span>
                )}
            </ProductSheetHeader>

            <div className="min-h-0 flex-1 overflow-hidden px-5 py-4 sm:px-6">
                <BrokerCedenteForm
                    embeddedInBento
                    surface="broker-sheet"
                    prefillRepresentante={prefillRepresentante}
                    onEditRepresentante={(representante) =>
                        setSubview({
                            kind: 'representante',
                            mode: 'edit',
                            id: representante.id,
                            nome: representante.nome,
                        })
                    }
                    onCreateRepresentante={() =>
                        setSubview({ kind: 'representante', mode: 'create' })
                    }
                />
            </div>
        </>
    );
}

