'use client';

import gsap from 'gsap';
import { useGSAP } from '@gsap/react';
import BrokerCedenteForm from '@/components/Forms/Broker/BrokerCedenteForm';
import { useBentoCockpitTheme } from '@/app/crm/broker/_hooks/useBentoCockpitTheme';
import { DocsSliderContextProvider } from '@/context/DocsSliderContext';
import type { OficioLockReason } from '@/functions/broker/oficio-lock-state';
import { cn } from '@/lib/utils';
import { Files, UserRound, type LucideIcon } from 'lucide-react';
import { useMemo, useRef, type ReactNode } from 'react';
import {
    BROKER_CEDENTE_BENTO_CARD_IDS,
    BROKER_CEDENTE_BENTO_GRID_GAP_PX,
    BrokerCedenteBentoCardId,
    CEDENTE_INFO_CARD_MAX_HEIGHT_CLASS,
    DEFAULT_BROKER_CEDENTE_BENTO_PLACEMENTS,
} from '../_types/cedente-bento';
import { BrokerDetailsBentoCard } from './BrokerDetailsBentoCard';
import { CedenteBentoCardHeader } from './CedenteBentoCardHeader';
import { DocumentsBentoPanel } from './DocumentsBentoPanel';

gsap.registerPlugin(useGSAP);

interface BrokerCedenteBentoGridProps {
    isLocked: boolean;
    lockReason?: OficioLockReason;
}

const CARD_META: Record<
    BrokerCedenteBentoCardId,
    { title: string; subtitle: string; icon: LucideIcon }
> = {
    'cedente-form': {
        title: 'Informações do cedente',
        subtitle: 'Dados cadastrais e vínculos',
        icon: UserRound,
    },
    documents: {
        title: 'Área de documentos',
        subtitle: 'Envio e aprovação de arquivos',
        icon: Files,
    },
};

function getViewportGridTemplateRows(rowCount: number): string {
    return `repeat(${rowCount}, minmax(0, 1fr))`;
}

function getStaticGridStyle(id: BrokerCedenteBentoCardId) {
    const placement = DEFAULT_BROKER_CEDENTE_BENTO_PLACEMENTS.find((candidate) => candidate.id === id)!;
    const { rect } = placement;

    return {
        gridColumn: `${rect.colStart} / ${rect.colEnd}`,
        gridRow: `${rect.rowStart} / ${rect.rowEnd}`,
    };
}

export function BrokerCedenteBentoGrid({ isLocked, lockReason }: BrokerCedenteBentoGridProps) {
    const mountRef = useRef<HTMLDivElement>(null);
    const { theme } = useBentoCockpitTheme();

    const rowCount = useMemo(
        () =>
            DEFAULT_BROKER_CEDENTE_BENTO_PLACEMENTS.reduce(
                (max, placement) => Math.max(max, placement.rect.rowEnd),
                1,
            ) - 1,
        [],
    );

    useGSAP(
        () => {
            gsap.fromTo(
                '[data-bento-card-id]',
                { y: 14, opacity: 0, filter: 'blur(8px)' },
                {
                    y: 0,
                    opacity: 1,
                    filter: 'blur(0px)',
                    stagger: 0.045,
                    duration: 0.42,
                    ease: 'power3.out',
                    clearProps: 'opacity,transform,filter',
                },
            );
        },
        { scope: mountRef },
    );

    function cardProps(id: BrokerCedenteBentoCardId) {
        const style = getStaticGridStyle(id);
        const meta = CARD_META[id];

        return {
            id,
            title: meta.title,
            headerVariant: 'accent' as const,
            headerSubtitle: meta.subtitle,
            headerIcon: meta.icon,
            gridColumn: style.gridColumn,
            gridRow: style.gridRow,
            draggable: false as const,
        };
    }

    const scrollableContentClass = 'flex h-0 min-h-0 flex-1 flex-col overflow-hidden p-2';

    const cards = (
        <>
            <BrokerDetailsBentoCard
                {...cardProps('cedente-form')}
                contentClassName={scrollableContentClass}
            >
                <BrokerCedenteForm isLocked={isLocked} lockReason={lockReason} embeddedInBento />
            </BrokerDetailsBentoCard>

            <BrokerDetailsBentoCard
                {...cardProps('documents')}
                contentClassName={scrollableContentClass}
            >
                <DocsSliderContextProvider>
                    <DocumentsBentoPanel isLocked={isLocked} lockReason={lockReason} />
                </DocsSliderContextProvider>
            </BrokerDetailsBentoCard>
        </>
    );

    const contentById: Record<BrokerCedenteBentoCardId, ReactNode> = {
        'cedente-form': (
            <div className="flex h-full min-h-0 flex-col overflow-hidden">
                <BrokerCedenteForm isLocked={isLocked} lockReason={lockReason} embeddedInBento />
            </div>
        ),
        documents: (
            <div className="h-[min(32rem,60vh)] min-h-0 overflow-hidden">
                <DocsSliderContextProvider>
                    <DocumentsBentoPanel isLocked={isLocked} lockReason={lockReason} />
                </DocsSliderContextProvider>
            </div>
        ),
    };

    return (
        <div className="h-full min-h-0">
            <div ref={mountRef} className="relative hidden h-full min-h-0 overflow-hidden p-4 xl:block">
                <div
                    className="relative grid h-full min-h-0 w-full grid-cols-12 items-stretch"
                    style={{

