'use client';

import { TooltipProvider } from '@/components/ui/tooltip';
import {
    situacaoJuridicaPageShellClass,
    situacaoJuridicaPageShellStyle,
} from '@/constants/due-diligence';
import { AnimatePresence } from 'framer-motion';
import { LoaderCircle } from 'lucide-react';
import dynamic from 'next/dynamic';
import { useRouter } from 'next/navigation';
import { useMemo, useState } from 'react';
import { useViewModelSituacaoJuridica } from '../../ViewModels/useViewModelSituacaoJuridica';
import type {
    ISituacaoJuridicaScreenViewProps,
    ISituacaoJuridicaViewProps,
} from '../../interfaces/situacaoJuridicaViews';
import { hasEntityId } from '../../types/dueItem';
import type { TVinculo } from '../../types/vinculo';
import { navigateToDueDiligenceMain } from '../../utils';
import { createSituacaoJuridicaServices } from '../../utils/createSituacaoJuridicaServices';
import { mapVinculoToFormValues } from '../../utils/mapVinculoToFormValues';
import { buildPessoaCertidoesUrl, buildPessoaProcessosUrl } from '../../utils/situacaoJuridica';
import { ResponsabilidadesAusentesAlert } from './Alerts';
import { KanbanView } from './Kanban/Kanban';
import { DeleteVinculoSituacaoJuridicaModal } from './Modals/DeleteVinculoSituacaoJuridicaModal';
import { ResponsaveisWrapper } from './ResponsaveisWrapper';
import { SituacaoJuridicaBackButton } from './SituacaoJuridicaBackButton';
import { SituacaoJuridicaHeader } from './SituacaoJuridicaHeader';
import { SituacaoJuridicaSkeleton } from './Skeletons';
import VinculosDrillView from './VinculosDrillView';
import { confirmDeleteVinculo } from './utils/confirmDeleteVinculo';

const CadastroCedenteSituacaoJuridicaModal = dynamic(
    () =>
        import('./CadastroCedenteModal').then(
            (module) => module.CadastroCedenteSituacaoJuridicaModal,
        ),
    {
        ssr: false,
        loading: () => (
            <div className="flex items-center justify-center p-8">
                <LoaderCircle className="h-6 w-6 animate-spin text-muted-foreground" />
            </div>
        ),
    },
);

const VincularCedenteExistenteSituacaoJuridicaModal = dynamic(
    () =>
        import('./VincularCedenteModal/VincularCedenteExistenteSituacaoJuridicaModal').then(
            (module) => module.VincularCedenteExistenteSituacaoJuridicaModal,
        ),
    {
        ssr: false,
        loading: () => (
            <div className="flex items-center justify-center p-8">
                <LoaderCircle className="h-6 w-6 animate-spin text-muted-foreground" />
            </div>
        ),
    },
);

const CadastroVinculoSituacaoJuridicaModal = dynamic(
    () =>
        import('./CadastroVinculoModal').then(
            (module) => module.CadastroVinculoSituacaoJuridicaModal,
        ),
    {
        ssr: false,
        loading: () => (
            <div className="flex items-center justify-center p-8">
                <LoaderCircle className="h-6 w-6 animate-spin text-muted-foreground" />
            </div>
        ),
    },
);

function View({ vm, due, onVoltar }: ISituacaoJuridicaScreenViewProps) {
    const router = useRouter();
    const [vinculoDeleteTarget, setVinculoDeleteTarget] = useState<TVinculo | null>(null);

    const handleConfirmDeleteVinculo = async () => {
        await confirmDeleteVinculo({
            vinculo: vinculoDeleteTarget,
            deleteVinculo: vm.handleDeleteVinculo,
            clearTarget: () => setVinculoDeleteTarget(null),
        });
    };

    if (vm.vinculosDrill.isOpen) {
        return (
            <>
                <div className="w-full">
                    <VinculosDrillView
                        vinculoRoot={vm.vinculoRoot}
                        vinculos={vm.vinculosDeeper}
                        isLoading={vm.isVinculosDeeperLoading}
                        drillStackIds={vm.vinculosDrillStack}
                        breadcrumbLabels={vm.vinculosDrillBreadcrumbLabels}
                        pessoaPendMap={vm.pessoaPendMap}
                        itemNomeCredor={due.nome_credor}
                        onVoltar={vm.handleVinculosDrillVoltar}
                        hasCedenteModifications={vm.hasCedenteModifications}
                        onOpenProcessos={(v) => {
                            if (!vm.responsavelProcessos) return;
                            router.push(
                                buildPessoaProcessosUrl(String(due.id), v.id, 'vinculo'),
                            );
                        }}
                        onOpenCertidoes={(v) => {
                            if (!vm.responsavelCertidoes) return;
                            router.push(
                                buildPessoaCertidoesUrl(String(due.id), v.id, 'vinculo'),
                            );
                        }}
                        onDrillDeeper={vm.handleDrillVinculoDeeper}
                        onEditVinculo={vm.handleOpenEditVinculo}
                        onDeleteVinculo={setVinculoDeleteTarget}
                        isExcluindoVinculo={vm.isExcluindoVinculo}
                        onAddVinculo={vm.handleAddVinculoFromDrill}
                        onSaveCedente={vm.handleSave}
                        isSaving={vm.isSaving}
                    />
                </div>
                {vm.vinculoModal.isOpen && vm.vinculoModalContext ? (
                    <CadastroVinculoSituacaoJuridicaModal
                        isOpen={vm.vinculoModal.isOpen}
                        mode={vm.vinculoModal.mode}
                        formSeedKey={
                            vm.vinculoModal.mode === 'edit' && vm.vinculoModal.vinculo
                                ? `edit:${vm.vinculoModal.vinculo.id}`
                                : `create:${vm.vinculoModal.tipo}:${vm.vinculoModal.subtipo ?? ''}:${vm.vinculoModal.pessoaPaiId ?? ''}`
                        }
                        context={vm.vinculoModalContext}
                        defaultValues={
                            vm.vinculoModal.mode === 'edit' && vm.vinculoModal.vinculo
                                ? mapVinculoToFormValues(vm.vinculoModal.vinculo)
                                : undefined
                        }
                        isSubmitting={vm.isSubmittingVinculo}
                        onClose={vm.handleCloseVinculoModal}
                        onSubmitCreate={vm.handleCadastrarVinculo}
                        onSubmitEdit={vm.handleEditarVinculo}
                    />
                ) : null}
                <DeleteVinculoSituacaoJuridicaModal
                    vinculo={vinculoDeleteTarget}
                    isOpen={Boolean(vinculoDeleteTarget)}
                    isDeleting={vm.isExcluindoVinculo}
                    onOpenChange={(isOpen) => {
                        if (!isOpen) {
                            setVinculoDeleteTarget(null);
                        }
                    }}
                    onConfirm={handleConfirmDeleteVinculo}
                />
            </>
        );
    }

    const activeCedenteItem = vm.cedentesState[vm.activeCedente] ?? null;
    const showResponsabilidadesAlert =
        !vm.responsavelProcessos || !vm.responsavelCertidoes;

    return (
        <TooltipProvider delayDuration={200}>
            <div className="relative w-full">
                <div
                    className={situacaoJuridicaPageShellClass}
                    style={situacaoJuridicaPageShellStyle}
                >

                    <div className="mb-4 flex items-center justify-between">
                        <SituacaoJuridicaBackButton
                            label="Voltar à due diligence"
                            onClick={onVoltar}
                        />
                        <div className="flex items-center gap-2">
                            <ResponsaveisWrapper
                                responsavelProcessos={vm.responsavelProcessos}
                                responsavelCertidoes={vm.responsavelCertidoes}
                                isRemovingResponsibilityProcessos={
                                    vm.isRemovingResponsibility.situacao_processual
                                }
                                isRemovingResponsibilityCertidoes={
                                    vm.isRemovingResponsibility.certidoes
                                }
                                onDesvincularProcessos={
                                    vm.handleDesvincularResponsabilidadeProcessos
                                }
                                onDesvincularCertidoes={
                                    vm.handleDesvincularResponsabilidadeCertidoes
                                }
                            />
                        </div>
                    </div>

                    <AnimatePresence>
                        {showResponsabilidadesAlert ? (
                            <ResponsabilidadesAusentesAlert
                                key="responsabilidades-ausentes-alert"
                                missingProcessos={!vm.responsavelProcessos}
                                missingCertidoes={!vm.responsavelCertidoes}
                                isLoadingProcessos={vm.isAssuming.situacao_processual}
                                isLoadingCertidoes={vm.isAssuming.certidoes}
                                onAssumirProcessos={vm.handleAssumirResponsabilidadeProcessos}
                                onAssumirCertidoes={vm.handleAssumirResponsabilidadeCertidoes}
                            />
                        ) : null}
                    </AnimatePresence>

                    <SituacaoJuridicaHeader
                        nomeCredor={due.nome_credor}
                        npuOriginario={due.npu_originario}
                    />

                    <KanbanView
                        activeCedenteItem={activeCedenteItem}
                        cedentesState={vm.cedentesState}
                        cessaoPercentualResumo={vm.cessaoPercentualResumo}
                        extratoId={vm.extratoId}
                        dueId={vm.dueId}
                        activeCedente={vm.activeCedente}
                        pessoaPendMap={vm.pessoaPendMap}
                        onSetActiveCedente={vm.setActiveCedente}
                        onAddCedente={vm.handleAddCedente}
                        onLinkExistingCedente={vm.handleOpenVincularCedenteExistente}
                        onRemoveCedente={vm.handleRemoveCedente}
                        isDesvinculandoCedente={vm.isRemovingCedente}
                        onUpdateCedente={vm.handleUpdateCedente}
                        onUpdateRepresentanteLegal={vm.handleUpdateRepresentanteLegal}
                        onAddVinculado={vm.handleAddVinculado}
                        onSave={vm.handleSave}
                        isSaving={vm.isSaving}
                        hasCedenteModifications={vm.hasCedenteModifications}
                        hasResponsavelProcessos={!!vm.responsavelProcessos}
                        hasResponsavelCertidoes={!!vm.responsavelCertidoes}
                        onOpenProcessos={(pessoa, tipoTitular) => {
                            if (!vm.responsavelProcessos) return;
                            if (!hasEntityId(pessoa)) return;
                            router.push(buildPessoaProcessosUrl(String(due.id), pessoa.id, tipoTitular));
                        }}
                        onOpenCertidoes={(pessoa, tipoTitular) => {
                            if (!vm.responsavelCertidoes) return;
                            if (!hasEntityId(pessoa)) return;
                            router.push(buildPessoaCertidoesUrl(String(due.id), pessoa.id, tipoTitular));
                        }}
                        onOpenVinculosDrill={vm.handleOpenVinculosDrill}
                        onEditVinculo={vm.handleOpenEditVinculo}
                        onDeleteVinculo={setVinculoDeleteTarget}
                        isExcluindoVinculo={vm.isExcluindoVinculo}
                        vinculosKanbanColumns={vm.vinculosKanbanColumns}
                        isVinculosLoading={vm.isVinculosLoading}
                        isCedenteColumnLoading={vm.isCedenteColumnLoading}
                    />

                </div>

                {vm.cadastroCedenteModal.isOpen &&
                    vm.cadastroCedenteModal.tipo &&
                    vm.extratoId &&
                    vm.cessaoPercentualResumo ? (
                    <CadastroCedenteSituacaoJuridicaModal
                        isOpen={vm.cadastroCedenteModal.isOpen}
                        cedenteTipo={vm.cadastroCedenteModal.tipo}
                        extratoId={vm.extratoId}
                        dueId={vm.dueId}
                        cessionPercentageAvailable={vm.cessaoPercentualResumo.disponivel}
                        onClose={vm.handleCloseCadastroCedenteModal}
                    />
                ) : null}

                {vm.vincularCedenteModal.isOpen && vm.extratoId && vm.cessaoPercentualResumo ? (
                    <VincularCedenteExistenteSituacaoJuridicaModal
                        isOpen={vm.vincularCedenteModal.isOpen}
                        extratoId={vm.extratoId}
                        dueId={vm.dueId}
                        cessionPercentageAvailable={vm.cessaoPercentualResumo.disponivel}
                        onClose={vm.handleCloseVincularCedenteModal}
                    />
                ) : null}

                {vm.vinculoModal.isOpen && vm.vinculoModalContext ? (
                    <CadastroVinculoSituacaoJuridicaModal
                        isOpen={vm.vinculoModal.isOpen}
                        mode={vm.vinculoModal.mode}
                        formSeedKey={
                            vm.vinculoModal.mode === 'edit' && vm.vinculoModal.vinculo
                                ? `edit:${vm.vinculoModal.vinculo.id}`
                                : `create:${vm.vinculoModal.tipo}:${vm.vinculoModal.subtipo ?? ''}`
                        }
                        context={vm.vinculoModalContext}
                        defaultValues={
                            vm.vinculoModal.mode === 'edit' && vm.vinculoModal.vinculo
                                ? mapVinculoToFormValues(vm.vinculoModal.vinculo)
                                : undefined
                        }
                        isSubmitting={vm.isSubmittingVinculo}
                        onClose={vm.handleCloseVinculoModal}

