export function SituacaoProcessualView({ dueId }: ISituacaoJuridicaViewProps) {
    const router = useRouter();
    const { situacaoJuridicaService } = useMemo(
        () => createSituacaoJuridicaServices(),
        [],
    );
    const vm = useViewModelSituacaoJuridica(dueId, situacaoJuridicaService);

    if (vm.isLoading || !vm.due) {
        return <SituacaoJuridicaSkeleton />;
    }

    return (
        <View
            vm={vm}
            due={vm.due}
            onVoltar={() => navigateToDueDiligenceMain(router)}
        />
    );
}
